import{readFileSync,writeFileSync}from"node:fs";import{dirname,join}from"node:path";import{fileURLToPath}from"node:url";const b=dirname(fileURLToPath(import.meta.url)),S=["AntDesign","Ionicons","MaterialIcons"].map(n=>({n,g:JSON.parse(readFileSync(join(b,"glyphmaps",`${n}.json`),"utf8"))})),T=S.reduce((a,s)=>a+Object.keys(s.g).length,0),K=s=>Object.entries(s.g).map(([n,c])=>`<button class=cell data-name="${n}" title="点击复制 ${n}"><span class=icon style="font-family:'${s.n}'">&#${c};</span><span class=name>${n}</span><span class=cp>U+${c.toString(16).toUpperCase()}</span></button>`).join(""),C=`<style>:root{color-scheme:dark;--bg:#161617;--surface:#1d1d1f;--hover:#2c2c2e;--text:#f5f5f7;--text-2:#a1a1a6;--text-3:#86868b;--faint:#48484a;--hairline:rgba(255,255,255,.1);--accent:#0a84ff;--r-card:18px;--r-pill:999px;--sh-panel:0 1px 3px rgba(0,0,0,.4),0 14px 40px rgba(0,0,0,.35);--ease-out-quart:cubic-bezier(.25,1,.5,1)}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font-family:-apple-system,BlinkMacSystemFont,'SF Pro Text','SF Pro Display','Helvetica Neue','PingFang SC','Hiragino Sans GB','Microsoft YaHei',sans-serif;-webkit-font-smoothing:antialiased;font-optical-sizing:auto}@font-face{font-family:AntDesign;src:url(Fonts/AntDesign.ttf) format("truetype")}@font-face{font-family:Ionicons;src:url(Fonts/Ionicons.ttf) format("truetype")}@font-face{font-family:MaterialIcons;src:url(Fonts/MaterialIcons.ttf) format("truetype")}header{position:sticky;top:0;z-index:10;background:rgba(22,22,23,.72);backdrop-filter:saturate(180%) blur(20px);-webkit-backdrop-filter:saturate(180%) blur(20px);border-bottom:1px solid var(--hairline)}.header-inner{max-width:1080px;margin:0 auto;padding:14px 22px;display:flex;align-items:baseline;gap:10px}h1{font-size:20px;font-weight:700;letter-spacing:-.02em;margin:0}.total{font-size:12px;color:var(--text-3);font-variant-numeric:tabular-nums}main{max-width:1080px;margin:0 auto;padding:28px 22px 60px}main>section+section{margin-top:clamp(34px,6vw,56px)}h2{font-size:17px;font-weight:600;letter-spacing:-.01em;margin:0 0 12px}h2 .count{margin-left:8px;font-size:11px;font-weight:500;color:var(--text-3);background:var(--surface);border:1px solid var(--hairline);border-radius:var(--r-pill);padding:2px 9px;font-variant-numeric:tabular-nums;vertical-align:1px}.panel{display:grid;grid-template-columns:repeat(auto-fill,minmax(104px,1fr));gap:1px;background:var(--hairline);border:1px solid var(--hairline);border-radius:var(--r-card);overflow:hidden;box-shadow:var(--sh-panel)}.cell{appearance:none;border:0;margin:0;background:var(--surface);padding:16px 8px 12px;display:flex;flex-direction:column;align-items:center;gap:8px;cursor:pointer;min-height:44px;font-family:inherit;transition:background 150ms var(--ease-out-quart),transform 100ms ease-out}.cell:hover{background:var(--hover)}.cell:active{transform:scale(.96)}.icon{font-size:28px;line-height:1;color:var(--text)}.name{font-size:11px;color:var(--text-2);word-break:break-all;line-height:1.4}.cp{font-size:10px;color:var(--faint);font-variant-numeric:tabular-nums}#toast{position:fixed;left:50%;bottom:32px;z-index:20;transform:translate(-50%,12px) scale(.98);opacity:0;background:rgba(22,22,23,.72);backdrop-filter:saturate(180%) blur(20px);-webkit-backdrop-filter:saturate(180%) blur(20px);border:1px solid var(--hairline);border-radius:var(--r-pill);padding:9px 18px;font-size:13px;color:var(--text);box-shadow:0 2px 8px rgba(0,0,0,.10),0 30px 80px rgba(0,0,0,.24);pointer-events:none;transition:opacity 250ms var(--ease-out-quart),transform 250ms var(--ease-out-quart)}#toast.show{opacity:1;transform:translate(-50%,0) scale(1)}#toast .n{color:var(--accent);font-weight:600}@media (prefers-reduced-motion:reduce){.cell,#toast{transition:opacity 200ms ease}.cell:active{transform:none}}@media (prefers-contrast:more){.panel{border-color:rgba(255,255,255,.35)}}</style>`;writeFileSync(join(b,"preview.html"),`<!DOCTYPE html><html lang=zh-CN><head><meta charset=UTF-8><meta name=viewport content="width=device-width,initial-scale=1"><title>图标对照表</title>${C}</head><body><header><div class=header-inner><h1>图标对照表</h1><span class=total>${T} 个图标 · 点击复制名称</span></div></header><main>${S.map(s=>`<section><h2>${s.n}<span class=count>${Object.keys(s.g).length}</span></h2><div class=panel>${K(s)}</div></section>`).join("")}</main><div id=toast role=status></div><script>const t=document.getElementById("toast");let e;document.querySelectorAll(".cell").forEach(c=>c.addEventListener("click",async()=>{const n=c.dataset.name;try{await navigator.clipboard.writeText(n)}catch{const a=document.createElement("textarea");a.value=n;document.body.appendChild(a);a.select();document.execCommand("copy");a.remove()}t.innerHTML='已复制 <span class=n></span>';t.querySelector(".n").textContent=n;t.classList.add("show");clearTimeout(e);e=setTimeout(()=>t.classList.remove("show"),1600)}));</script></body></html>`);console.log(`written: ${join(b,"preview.html")} (${T} icons)`)
